-- ─────────────────────────────────────────────────────────────
-- Glowe Play — master badge catalog (360) import
-- Run ONCE in Supabase → SQL Editor, after badges.sql/badges-spreads.sql.
-- Idempotent: adds columns if missing, upserts by id, never deletes,
-- and never overwrites existing artwork with blank CSV values.
-- ─────────────────────────────────────────────────────────────

-- Relax legacy check constraints: the catalog's `type` now includes
-- growth/everyday-magic, and templates include chapter/signature.
alter table public.badges drop constraint if exists badges_type_check;
alter table public.badges drop constraint if exists badges_template_check;

alter table public.badges
  add column if not exists min_age_months integer,
  add column if not exists max_age_months integer,
  add column if not exists age_stage text,
  add column if not exists age_stage_label text,
  add column if not exists category text,
  add column if not exists subcategory text,
  add column if not exists repeatable boolean not null default false,
  add column if not exists cadence text not null default 'once',
  add column if not exists season text not null default 'any',
  add column if not exists estimated_minutes integer,
  add column if not exists parent_effort text,
  add column if not exists location text,
  add column if not exists supplies text[] not null default '{}',
  add column if not exists book_priority integer not null default 5,
  add column if not exists sensitivity text not null default 'standard',
  add column if not exists featured boolean not null default false,
  add column if not exists series text,
  add column if not exists prompt text,
  add column if not exists photo_prompt text,
  add column if not exists voice_prompt text,
  add column if not exists journal_prompt text,
  add column if not exists tags text[] not null default '{}',
  add column if not exists source text;

create index if not exists badges_age_idx on public.badges (min_age_months, max_age_months);
create index if not exists badges_category_idx on public.badges (category);
create index if not exists badges_stage_idx on public.badges (age_stage);

begin;

insert into public.badges (
  id, line1, line2, type, icon_emoji, verb, template, accent, media, how_to_earn, sort_order, is_active, image_new, image_progress, image_url, description, min_age_months, max_age_months, age_stage, age_stage_label, category, subcategory, repeatable, cadence, season, estimated_minutes, parent_effort, location, supplies, book_priority, sensitivity, featured, series, prompt, photo_prompt, voice_prompt, journal_prompt, tags, source
