on conflict (id) do update set
  line1 = excluded.line1,
  line2 = excluded.line2,
  type = excluded.type,
  icon_emoji = excluded.icon_emoji,
  verb = excluded.verb,
  template = excluded.template,
  accent = excluded.accent,
  media = excluded.media,
  how_to_earn = excluded.how_to_earn,
  sort_order = excluded.sort_order,
  is_active = excluded.is_active,
  image_new = coalesce(excluded.image_new, public.badges.image_new),
  image_progress = coalesce(excluded.image_progress, public.badges.image_progress),
  image_url = coalesce(excluded.image_url, public.badges.image_url),
  description = excluded.description,
  min_age_months = excluded.min_age_months,
  max_age_months = excluded.max_age_months,
  age_stage = excluded.age_stage,
  age_stage_label = excluded.age_stage_label,
  category = excluded.category,
  subcategory = excluded.subcategory,
  repeatable = excluded.repeatable,
  cadence = excluded.cadence,
  season = excluded.season,
  estimated_minutes = excluded.estimated_minutes,
  parent_effort = excluded.parent_effort,
  location = excluded.location,
  supplies = excluded.supplies,
  book_priority = excluded.book_priority,
  sensitivity = excluded.sensitivity,
  featured = excluded.featured,
  series = excluded.series,
  prompt = excluded.prompt,
  photo_prompt = excluded.photo_prompt,
  voice_prompt = excluded.voice_prompt,
  journal_prompt = excluded.journal_prompt,
  tags = excluded.tags,
  source = excluded.source,
  updated_at = now();

commit;

notify pgrst, 'reload schema';